        # Convert to float, replacing comma with dot for string decimals
        if isinstance(x, str):
            return float(x.replace(',', '.'))
        return float(x)

    fa = to_float(a)
    fb = to_float(b)

    if fa > fb:
        return a
    elif fb > fa:
        return b
    else:
        return None

